SEARCH_SCRIPT = '\n        (limit) => {\n          const decoded = (value) => {\n  let text=String(value || \'\');\n  for(let i=0;i<2 && /%[0-9a-f]{2}/i.test(text);i++) {\n    try { const next=decodeURIComponent(text); if(next===text) break; text=next; } catch(_) { break; }\n  }\n  return text;\n};\nconst absoluteImage = (value) => {\n  let text=decoded(value).trim(); if(text.startsWith(\'//\')) text=\'https:\'+text;\n  if(!/^https?:\\/\\//i.test(text)) return \'\';\n  try { const u=new URL(text); if([\'search.jd.com\',\'search.360buy.com\'].includes(u.hostname)) return \'\'; return u.href; } catch(_) { return \'\'; }\n};\nconst amount = (value) => decoded(value).replace(/\\s+/g,\'\').trim();\n\n          const clean = (value, max = 500) => {\n            const text = decoded(value).replace(/\\s+/g, \' \').trim();\n            return max && text.length > max ? text.slice(0, max - 1) + \'…\' : text;\n          };\n          const selectors = [\n            \'[data-sku]\',\n            \'[class*="goodsCardWrapper"]\',\n            \'#J_goodsList .gl-item\',\n            \'li.gl-item\',\n            \'[class*="goods-list"] [class*="item"]\',\n            \'[class*="product-list"] [class*="item"]\',\n            \'div[class*="item"]:has(a[href*="item.jd.com"])\',\n          ];\n          let cards = [];\n          for (const selector of selectors) {\n            try {\n              const found = document.querySelectorAll(selector);\n              if (found.length) {\n                cards = [...found];\n                break;\n              }\n            } catch (_) {}\n          }\n          cards = cards.slice(0, limit);\n          if (cards.length) return cards.map((card) => {\n            const link=card.querySelector(\'a[href*="item.jd.com"], a[href*="chat.jd.com"][href*="pid="]\');\n            let meta=null; try { meta=new URL(link?.href || \'\'); } catch(_) {}\n            const sku=card.getAttribute(\'data-sku\') || meta?.searchParams.get(\'pid\') || \'\';\n            const titleNode=card.querySelector(\'.p-name em, .p-name, [class*="title" i], [class*="name" i]\');\n            const image=card.querySelector(\'img\');\n            const title=clean(titleNode?.innerText || link?.innerText || link?.getAttribute(\'title\') || meta?.searchParams.get(\'wname\') || image?.alt,300);\n            const price=amount(card.querySelector(\'.p-price i, .p-price, [class*="price" i]\')?.innerText || \'\');\n            const shop=clean(card.querySelector(\'.p-shop a, .p-shop, [class*="shop" i]\')?.innerText || meta?.searchParams.get(\'seller\'),120);\n            const itemUrl=meta && /^item\\.(?:jd|360buy)\\.com$/.test(meta.hostname) ? meta.href : (/^\\d+$/.test(sku)?`https://item.jd.com/${sku}.html`:\'\');\n            const imageUrl=[image?.currentSrc,image?.src,image?.getAttribute(\'data-lazy-img\'),image?.getAttribute(\'data-img\'),meta?.searchParams.get(\'imgUrl\')].map(absoluteImage).find(Boolean) || \'\';\n            return {title,price_text:price,shop,comment_text:clean(card.querySelector(\'.p-commit a, .p-commit\')?.innerText),url:itemUrl,image:imageUrl};\n          });\n          const out = [];\n          const seen = new Set();\n          for (const link of document.querySelectorAll(\'a[href*="chat.jd.com"][href*="pid="]\')) {\n            try {\n              const url = new URL(link.href);\n              const pid = url.searchParams.get(\'pid\');\n              if (!pid || seen.has(pid)) continue;\n              const title = clean(link.getAttribute(\'title\') || url.searchParams.get(\'wname\') || link.innerText, 300);\n              if (!title) continue;\n              seen.add(pid);\n              out.push({\n                title,\n                price_text: \'\',\n                shop: clean(url.searchParams.get(\'seller\'), 120),\n                comment_text: clean(url.searchParams.get(\'commentNum\'), 80),\n                url: `https://item.jd.com/${pid}.html`,\n                image: absoluteImage(url.searchParams.get(\'imgUrl\'))\n              });\n              if (out.length >= limit) break;\n            } catch (_) {}\n          }\n          return out;\n        }\n        '

DETAIL_SCRIPT = '\n        (selectors) => {\n          const decoded = (value) => {\n  let text=String(value || \'\');\n  for(let i=0;i<2 && /%[0-9a-f]{2}/i.test(text);i++) {\n    try { const next=decodeURIComponent(text); if(next===text) break; text=next; } catch(_) { break; }\n  }\n  return text;\n};\nconst absoluteImage = (value) => {\n  let text=decoded(value).trim(); if(text.startsWith(\'//\')) text=\'https:\'+text;\n  if(!/^https?:\\/\\//i.test(text)) return \'\';\n  try { const u=new URL(text); if([\'search.jd.com\',\'search.360buy.com\'].includes(u.hostname)) return \'\'; return u.href; } catch(_) { return \'\'; }\n};\nconst amount = (value) => decoded(value).replace(/\\s+/g,\'\').trim();\n\n          const clean = (value, max = 500) => {\n            const text = decoded(value).replace(/\\s+/g, \' \').trim();\n            return max && text.length > max ? text.slice(0, max - 1) + \'…\' : text;\n          };\n\nconst titleText=(value)=>{\n let text=String(value||\'\');\n for(let i=0;i<2 && /%[0-9a-f]{2}/i.test(text);i++){try{const next=decodeURIComponent(text);if(next===text)break;text=next;}catch(_){break;}}\n return text.replace(/【行情\\s*报价\\s*价格\\s*评测】\\s*[-－–—|]\\s*京东.*$/i,\'\')\n .replace(/\\s*[-_－–—|]\\s*(?:京东|JD\\.COM).*$/i,\'\').replace(/\\s+/g,\' \').trim();\n};\nconst productTitle=()=>{\n const reliable=value=>value.length>=3 && !/^(?:京东(?:商城)?|JD\\.COM|商品详情|加载中[.。…]*)$/i.test(value);\n const doc=titleText(document.title); if(reliable(doc)) return doc;\n for(const selector of [\'.sku-name\',\'.page-right-name\',\'[class*="product-name" i]\', \'meta[property="og:title"]\']){\n  const el=document.querySelector(selector);const text=titleText(el?.innerText||el?.getAttribute?.(\'content\'));\n  if(reliable(text)) return text;\n }\n return \'\';\n};\nconst displayProductPrice=()=>{\n for(const selector of [\'.page-right-price\',\'.p-price .price\',\'.summary-price .price\',\'[class*="price" i]\']){\n  const nodes=[...document.querySelectorAll(selector)];\n  if(!nodes.length){const first=document.querySelector(selector);if(first)nodes.push(first);}\n  for(const el of nodes){\n   if(/skeleton/i.test(String(el.className||\'\'))) continue;\n   const text=String(el.innerText||\'\').replace(/[\\s,]+/g,\'\');\n   const match=text.match(/(?:¥|￥|RMB|CNY)([0-9]+(?:\\.[0-9]{1,2})?)/i);\n   if(match) return \'¥\'+match[1];\n  }\n }\n return \'\';\n};\n\n          const firstText = (items) => {\n            for (const selector of items) {\n              const el = document.querySelector(selector);\n              const text = el?.innerText?.trim() || el?.getAttribute?.(\'content\')?.trim();\n              if (text) return clean(text);\n            }\n            return \'\';\n          };\n          const jsonLd = [];\n          for (const node of document.querySelectorAll(\'script[type="application/ld+json"]\')) {\n            try { jsonLd.push(JSON.parse(node.textContent || \'null\')); } catch (_) {}\n          }\n          const specs = [];\n          for (const selector of selectors.specs) {\n            for (const el of document.querySelectorAll(selector)) {\n              const text = (el.innerText || \'\').trim();\n              if (text && text.length < 500) specs.push(text);\n              if (specs.length >= 80) break;\n            }\n            if (specs.length >= 80) break;\n          }\n          const productParameters = [];\n          const parameterSeen = new Set();\n          const addParameter = (name, value, group = \'\') => {\n            name = clean(name, 120).replace(/[：:]\\s*$/, \'\');\n            value = clean(value, 500);\n            group = clean(group, 120);\n            if (!name || !value || name === value) return;\n            const key = `${group}\\u0000${name}\\u0000${value}`;\n            if (parameterSeen.has(key)) return;\n            parameterSeen.add(key);\n            productParameters.push({name, value, group});\n          };\n          const splitParameterText = (text) => {\n            text = clean(text, 600);\n            const index = text.search(/[：:]/);\n            if (index <= 0 || index >= text.length - 1) return null;\n            return [text.slice(0, index), text.slice(index + 1)];\n          };\n          for (const selector of selectors.specs) {\n            for (const el of document.querySelectorAll(selector)) {\n              const pair = splitParameterText(el.innerText || \'\');\n              if (pair) addParameter(pair[0], pair[1]);\n              if (productParameters.length >= 100) break;\n            }\n            if (productParameters.length >= 100) break;\n          }\n          for (const section of document.querySelectorAll(\'.Ptable-item, [class*="Ptable"], [class*="parameter"], [class*="Parameter"]\')) {\n            const group = clean(section.querySelector(\'h3, h4, .Ptable-tit\')?.innerText || \'\');\n            for (const row of section.querySelectorAll(\'dl, tr, li\')) {\n              const name = clean(row.querySelector(\'dt, th, .name, [class*="name"]\')?.innerText || \'\');\n              const value = clean(row.querySelector(\'dd, td, .value, [class*="value"]\')?.innerText || \'\');\n              if (name && value) addParameter(name, value, group);\n              const pair = splitParameterText(row.innerText || \'\');\n              if (pair) addParameter(pair[0], pair[1], group);\n              if (productParameters.length >= 100) break;\n            }\n            if (productParameters.length >= 100) break;\n          }\n          const detailParameters = [];\n          const detailParameterSeen = new Set();\n          const addDetailParameter = (name, value, group = \'商品详情\') => {\n            name = clean(name, 120).replace(/[：:]\\s*$/, \'\');\n            value = clean(value, 500);\n            group = clean(group, 120) || \'商品详情\';\n            if (!name || !value || name === value) return;\n            const key = `${group}\\u0000${name}\\u0000${value}`;\n            if (detailParameterSeen.has(key)) return;\n            detailParameterSeen.add(key);\n            detailParameters.push({name, value, group});\n          };\n          const detailRoots = [\n            ...document.querySelectorAll(\'#detail, #J-detail, .detail, .goods-detail, [class*="detail"], [class*="Detail"]\')\n          ];\n          const rootSeen = new Set();\n          for (const root of detailRoots) {\n            if (!root || rootSeen.has(root)) continue;\n            rootSeen.add(root);\n            const rootText = clean(root.innerText || root.textContent || \'\', 3000);\n            if (!rootText.includes(\'商品详情\') && !root.querySelector(\'.Ptable, .Ptable-item, .p-parameter-list, .parameter2\')) continue;\n            for (const section of root.querySelectorAll(\'.Ptable-item, .Ptable, .p-parameter, .parameter2, .p-parameter-list\')) {\n              const group = clean(section.querySelector(\'h3, h4, .Ptable-tit\')?.innerText || \'商品详情\');\n              for (const row of section.querySelectorAll(\'dl, tr, li\')) {\n                const name = clean(row.querySelector(\'dt, th, .name, [class*="name"]\')?.innerText || \'\');\n                const value = clean(row.querySelector(\'dd, td, .value, [class*="value"]\')?.innerText || \'\');\n                if (name && value) addDetailParameter(name, value, group);\n                const pair = splitParameterText(row.innerText || \'\');\n                if (pair) addDetailParameter(pair[0], pair[1], group);\n                if (detailParameters.length >= 100) break;\n              }\n              if (detailParameters.length >= 100) break;\n            }\n            if (detailParameters.length >= 100) break;\n          }\n          const textOf = (root, selectorList) => {\n            for (const selector of selectorList) {\n              const el = root.querySelector(selector);\n              const text = clean(el?.innerText || el?.textContent || \'\', 1200);\n              if (text) return text;\n            }\n            return \'\';\n          };\n          const helpfulCount = (text) => {\n            text = clean(text, 2000);\n            const patterns = [\n              /(\\d+)\\s*(?:人)?(?:点赞|赞|有用|认为有用)/,\n              /(?:点赞|赞|有用|认为有用)\\D{0,8}(\\d+)/\n            ];\n            for (const pattern of patterns) {\n              const match = text.match(pattern);\n              if (match) return Number(match[1]);\n            }\n            return null;\n          };\n          const positiveTerms = [\'好用\', \'满意\', \'推荐\', \'不错\', \'很好\', \'超香\', \'方便\', \'简单\', \'值得\', \'性价比\', \'喜欢\', \'大品牌\', \'香甜\', \'粒粒分明\', \'完美\', \'省心\', \'治愈\', \'强烈推荐\', \'闭眼冲\', \'稳定\', \'灵敏\', \'流畅\', \'可爱\', \'实用\'];\n          const negativeTerms = [\'不满意\', \'不好用\', \'差评\', \'很差\', \'垃圾\', \'失望\', \'退货\', \'坏了\', \'破损\', \'有异味\', \'夹生饭\', \'溢锅\', \'太慢了\', \'噪音大\', \'漏水\', \'不推荐\', \'难用\', \'踩雷\', \'虚假\', \'欺骗\', \'套路\'];\n          const negationPhrases = [\'后悔没有早点\', \'没有异味\', \'无异味\', \'不粘锅\', \'不夹生\', \'噪音小\', \'噪音低\', \'不费力\'];\n          const isTrulyNegative = (text, term) => {\n            const index = text.indexOf(term);\n            if (index < 0) return false;\n            if (negationPhrases.some((phrase) => text.includes(phrase))) return false;\n            const before = text.slice(Math.max(0, index - 3), index);\n            if (/[没无非少小零]$/.test(before)) return false;\n            return true;\n          };\n          const reviewNodes = [];\n          const reviewNodeSeen = new Set();\n          for (const selector of selectors.review_items) {\n            for (const node of document.querySelectorAll(selector)) {\n              if (reviewNodeSeen.has(node)) continue;\n              reviewNodeSeen.add(node);\n              reviewNodes.push(node);\n              if (reviewNodes.length >= 80) break;\n            }\n            if (reviewNodes.length >= 80) break;\n          }\n          const reviews = [];\n          const reviewSeen = new Set();\n          for (const node of reviewNodes) {\n            const allText = clean(node.innerText || node.textContent || \'\', 2000);\n            let content = textOf(node, selectors.review_content);\n            if (!content) content = allText;\n            const user = textOf(node, selectors.review_user);\n            const time = textOf(node, selectors.review_time);\n            const variant = textOf(node, selectors.review_variant);\n            content = clean(content.replace(user, \'\').replace(time, \'\').replace(variant, \'\'), 800);\n            if (content.length < 8) continue;\n            const key = `${user}\\u0000${content}`;\n            if (reviewSeen.has(key)) continue;\n            reviewSeen.add(key);\n            const positive = positiveTerms.some((term) => content.includes(term));\n            const negative = negativeTerms.some((term) => isTrulyNegative(content, term));\n            reviews.push({\n              user: clean(user, 80),\n              content,\n              helpful_count: helpfulCount(allText),\n              time: clean(time, 80),\n              variant: clean(variant, 160),\n              sentiment: negative ? \'negative\' : (positive ? \'positive\' : \'\')\n            });\n          }\n          const reviewSort = (a, b) => (b.helpful_count || 0) - (a.helpful_count || 0);\n          const highPraiseReviews = reviews\n            .filter((review) => review.sentiment === \'positive\')\n            .sort(reviewSort)\n            .slice(0, 5);\n          const highDissatisfiedReviews = reviews\n            .filter((review) => review.sentiment === \'negative\')\n            .sort(reviewSort)\n            .slice(0, 2);\n          const images = [];\n          const ogImage = document.querySelector(\'meta[property="og:image"]\')?.content;\n          \n          for (const img of document.querySelectorAll(\'#spec-img, #spec-list img, .preview img, .preview-wrap img, .page-left img\')) {\n            const src = [img.currentSrc,img.src,img.getAttribute(\'data-origin\'),img.getAttribute(\'data-src\'),img.getAttribute(\'data-lazy-img\')].map(absoluteImage).find(Boolean) || \'\';\n            const w = img.naturalWidth || img.width || 0;\n            const h = img.naturalHeight || img.height || 0;\n            if (src && (w >= 200 || h >= 200) && !images.includes(src)) images.push(src);\n            if (images.length >= 30) break;\n          }\n          if (!images.length && absoluteImage(ogImage)) images.push(absoluteImage(ogImage));\n          const bodyText = document.body?.innerText || \'\';\n          return {\n            title: productTitle(),\n            price_text: displayProductPrice(),\n            shop: firstText(selectors.shop),\n            review_text: firstText(selectors.reviews),\n            sales_text: firstText(selectors.sales),\n            specs,\n            product_parameters: productParameters,\n            detail_product_parameters: detailParameters,\n            high_praise_reviews: highPraiseReviews,\n            high_dissatisfied_reviews: highDissatisfiedReviews,\n            images,\n            json_ld: jsonLd,\n            meta: {\n              og_title: document.querySelector(\'meta[property="og:title"]\')?.content || \'\',\n              description: document.querySelector(\'meta[name="description"]\')?.content || document.querySelector(\'meta[property="og:description"]\')?.content || \'\',\n              canonical: document.querySelector(\'link[rel="canonical"]\')?.href || \'\'\n            },\n            body_text: bodyText\n          };\n        }\n        '

DETAIL_SELECTORS = {'title': ['.sku-name', '#name h1', 'h1', "meta[property='og:title']"], 'price': ['.p-price .price', '.summary-price .price', "[class*='price'] [class*='price']", "[class*='price']"], 'shop': ['.name a', '.shop-name', "[class*='shopName']", "[class*='shop-name']"], 'reviews': ['.comment-count .count', '#comment-count', "[class*='comment']"], 'sales': ["[class*='sales']", "[class*='deal']"], 'specs': ['#detail .p-parameter-list li', '.parameter2 li', '.Ptable-item', "[class*='parameter'] li"], 'review_items': ['.comment-item', '.J-comment-item', "[class*='comment-item']", "[class*='CommentItem']"], 'review_user': ['.user-info', '.nickname', "[class*='user']", "[class*='User']"], 'review_content': ['.comment-con', '.comment-content', "[class*='content']", "[class*='Content']"], 'review_time': ['.order-info', '.comment-time', "[class*='time']", "[class*='Time']"], 'review_variant': ['.order-info', '.comment-column', "[class*='sku']", "[class*='Sku']"]}

READINESS_SCRIPT = 'async (statusChecker) => { /* JD_READY: bounded DOM wait only; no navigation/refresh/network */\n\nconst titleText=(value)=>{\n let text=String(value||\'\');\n for(let i=0;i<2 && /%[0-9a-f]{2}/i.test(text);i++){try{const next=decodeURIComponent(text);if(next===text)break;text=next;}catch(_){break;}}\n return text.replace(/【行情\\s*报价\\s*价格\\s*评测】\\s*[-－–—|]\\s*京东.*$/i,\'\')\n .replace(/\\s*[-_－–—|]\\s*(?:京东|JD\\.COM).*$/i,\'\').replace(/\\s+/g,\' \').trim();\n};\nconst productTitle=()=>{\n const reliable=value=>value.length>=3 && !/^(?:京东(?:商城)?|JD\\.COM|商品详情|加载中[.。…]*)$/i.test(value);\n const doc=titleText(document.title); if(reliable(doc)) return doc;\n for(const selector of [\'.sku-name\',\'.page-right-name\',\'[class*="product-name" i]\', \'meta[property="og:title"]\']){\n  const el=document.querySelector(selector);const text=titleText(el?.innerText||el?.getAttribute?.(\'content\'));\n  if(reliable(text)) return text;\n }\n return \'\';\n};\nconst displayProductPrice=()=>{\n for(const selector of [\'.page-right-price\',\'.p-price .price\',\'.summary-price .price\',\'[class*="price" i]\']){\n  const nodes=[...document.querySelectorAll(selector)];\n  if(!nodes.length){const first=document.querySelector(selector);if(first)nodes.push(first);}\n  for(const el of nodes){\n   if(/skeleton/i.test(String(el.className||\'\'))) continue;\n   const text=String(el.innerText||\'\').replace(/[\\s,]+/g,\'\');\n   const match=text.match(/(?:¥|￥|RMB|CNY)([0-9]+(?:\\.[0-9]{1,2})?)/i);\n   if(match) return \'¥\'+match[1];\n  }\n }\n return \'\';\n};\n\n const deadline=Date.now()+10000;\n while(true){\n  const signal=statusChecker();\n  if(signal.risk_control||signal.requires_user_login) return JSON.stringify({ready:false,risk_control:!!signal.risk_control,requires_user_login:!!signal.requires_user_login});\n  if(productTitle()&&displayProductPrice()) return JSON.stringify({ready:true,timed_out:false});\n  const remaining=deadline-Date.now();\n  if(remaining<=0) return JSON.stringify({ready:false,timed_out:true});\n  await new Promise(resolve=>setTimeout(resolve,Math.min(200,remaining)));\n }\n}'
